import React, { useEffect, useState } from "react";
import {
  Box,
  AppBar,
  Toolbar,
  Typography,
  Table,
  TableHead,
  TableRow,
  TableCell,
  TableBody,
  TableContainer,
  Paper,
  Button,
  Chip,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
} from "@mui/material";

import { fetchRequests, assignRequest, updateStatus } from "./api";

export default function Admin({ onLogout }) {
  const [requests, setRequests] = useState([]);
  const [loading, setLoading] = useState(false);
  const [openAssign, setOpenAssign] = useState(false);
  const [selectedId, setSelectedId] = useState(null);
  const [driverName, setDriverName] = useState("");

  async function load() {
    setLoading(true);
    try {
      const data = await fetchRequests();
      setRequests(data);
    } catch (e) {
      alert("Session expired. Please login again.");
      onLogout();
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    load();
    const t = setInterval(load, 30000);
    return () => clearInterval(t);
  }, []);

  const handleAssign = (id) => {
    setSelectedId(id);
    setOpenAssign(true);
  };

  const submitAssign = async () => {
    await assignRequest(selectedId, driverName);
    setOpenAssign(false);
    setDriverName("");
    load();
  };

  const markComplete = async (id) => {
    await updateStatus(id, "Completed");
    load();
  };

  const getStatusColor = (status) => {
    switch (status) {
      case "Pending":
        return "warning";
      case "Assigned":
        return "info";
      case "Completed":
        return "success";
      default:
        return "default";
    }
  };

  return (
    <>
      {/* TOP BAR */}
      <AppBar position="static">
        <Toolbar sx={{ display: "flex", justifyContent: "space-between" }}>
          <Typography variant="h6">TROQ Admin Dashboard</Typography>
          <Button color="inherit" onClick={onLogout}>
            Logout
          </Button>
        </Toolbar>
      </AppBar>

      <Box sx={{ padding: 4 }}>
        <Typography variant="h5" gutterBottom>
          Requests
        </Typography>

        <TableContainer component={Paper} elevation={3}>
          <Table>
            <TableHead>
              <TableRow sx={{ backgroundColor: "#f5f5f5" }}>
                <TableCell>ID</TableCell>
                <TableCell>Name</TableCell>
                <TableCell>Phone</TableCell>
                <TableCell>Pickup → Drop</TableCell>
                <TableCell>Date/Time</TableCell>
                <TableCell>Service</TableCell>
                <TableCell>Status</TableCell>
                <TableCell>Assigned</TableCell>
                <TableCell>Actions</TableCell>
              </TableRow>
            </TableHead>

            <TableBody>
              {requests.map((r) => (
                <TableRow key={r.id}>
                  <TableCell>{r.id}</TableCell>
                  <TableCell>{r.name}</TableCell>
                  <TableCell>{r.phone}</TableCell>
                  <TableCell>
                    {r.pickup} → {r.drop_location}
                  </TableCell>
                  <TableCell>{r.date_time}</TableCell>
                  <TableCell>{r.service_type}</TableCell>

                  <TableCell>
                    <Chip
                      label={r.status}
                      color={getStatusColor(r.status)}
                      variant="outlined"
                    />
                  </TableCell>

                  <TableCell>{r.assigned_to || "-"}</TableCell>

                  <TableCell>
                    <Button
                      size="small"
                      variant="contained"
                      sx={{ mr: 1 }}
                      onClick={() => handleAssign(r.id)}
                    >
                      Assign
                    </Button>

                    <Button
                      size="small"
                      color="success"
                      variant="contained"
                      onClick={() => markComplete(r.id)}
                    >
                      Done
                    </Button>
                  </TableCell>
                </TableRow>
              ))}

              {requests.length === 0 && (
                <TableRow>
                  <TableCell colSpan={9} align="center">
                    No requests yet.
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </TableContainer>
      </Box>

      {/* Assign Driver Modal */}
      <Dialog open={openAssign} onClose={() => setOpenAssign(false)}>
        <DialogTitle>Assign Driver</DialogTitle>
        <DialogContent>
          <TextField
            fullWidth
            label="Driver Name"
            value={driverName}
            onChange={(e) => setDriverName(e.target.value)}
            sx={{ mt: 1 }}
          />
        </DialogContent>

        <DialogActions>
          <Button onClick={() => setOpenAssign(false)}>Cancel</Button>
          <Button onClick={submitAssign} variant="contained">
            Assign
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
}
